import { QueryBuilder, QueryResultErrors, SolidityVerifierParameters } from './types.js';
export { QueryBuilderResult, QueryResultError, SolidityCommitments, SolidityProofVerificationData, SolidityServiceConfig } from './types.js';
import { ProofMode, ProofResult, QueryResult, NullifierType, SupportedChain } from '@zkpassport/utils';
export * from '@zkpassport/utils';
export { ASEAN_COUNTRIES, EEA_COUNTRIES, EU_COUNTRIES, MERCOSUR_COUNTRIES, SANCTIONED_COUNTRIES, SCHENGEN_COUNTRIES } from '@zkpassport/utils';

declare class ZKPassport {
    private domain;
    private topicToConfig;
    private topicToLocalConfig;
    private topicToPublicKey;
    private topicToBridge;
    private topicToRequestReceived;
    private topicToService;
    private topicToProofs;
    private topicToExpectedProofCount;
    private topicToFailedProofCount;
    private topicToResults;
    private onRequestReceivedCallbacks;
    private onGeneratingProofCallbacks;
    private onBridgeConnectCallbacks;
    private onProofGeneratedCallbacks;
    private onResultCallbacks;
    private onRejectCallbacks;
    private onErrorCallbacks;
    private normalizeDomain;
    constructor(_domain?: string);
    private handleResult;
    private setExpectedProofCount;
    /**
     * @notice Handle an encrypted message.
     * @param request The request.
     * @param outerRequest The outer request.
     */
    private handleEncryptedMessage;
    private getZkPassportRequest;
    /**
     * @notice Create a new request
     * @param name Your service name
     * @param logo The logo of your service
     * @param purpose To explain what you want to do with the user's data
     * @param scope Scope this request to a specific use case
     * @param projectID The project ID of your service
     * @param validity How many seconds ago the proof checking the expiry date of the ID should have been generated
     * @param devMode Whether to enable dev mode. This will allow you to verify mock proofs (i.e. from ZKR)
     * @returns The query builder object.
     */
    request({ name, logo, purpose, scope, projectID, mode, validity, devMode, topicOverride, keyPairOverride, cloudProverUrl, bridgeUrl, }: {
        name: string;
        logo: string;
        purpose: string;
        scope?: string;
        mode?: ProofMode;
        projectID?: string;
        validity?: number;
        devMode?: boolean;
        topicOverride?: string;
        keyPairOverride?: {
            privateKey: Uint8Array;
            publicKey: Uint8Array;
        };
        cloudProverUrl?: string;
        bridgeUrl?: string;
    }): Promise<QueryBuilder>;
    /**
     * @notice Verify the proofs received from the mobile app.
     * @param proofs The proofs to verify.
     * @param queryResult The query result to verify against
     * @param validity How many seconds ago the proof checking the expiry date of the ID should have been generated
     * @param scope Scope this request to a specific use case
     * @param devMode Whether to enable dev mode. This will allow you to verify mock proofs (i.e. from ZKR)
     * @param writingDirectory The directory (e.g. `./tmp`) where the necessary temporary artifacts for verification are written to.
     * It should only be needed when running the `verify` function on a server with restricted write access (e.g. Vercel)
     * @returns An object containing the unique identifier associated to the user
     * and a boolean indicating whether the proofs were successfully verified.
     */
    verify({ proofs, queryResult, validity, scope, devMode, writingDirectory, }: {
        proofs: Array<ProofResult>;
        queryResult: QueryResult;
        validity?: number;
        scope?: string;
        devMode?: boolean;
        writingDirectory?: string;
    }): Promise<{
        uniqueIdentifier: string | undefined;
        uniqueIdentifierType: NullifierType | undefined;
        verified: boolean;
        queryResultErrors?: Partial<QueryResultErrors>;
    }>;
    getSolidityVerifierDetails(network: SupportedChain): {
        address: `0x${string}`;
        functionName: string;
        abi: {
            type: "function" | "event" | "constructor";
            name: string;
            inputs: {
                name: string;
                type: string;
                internalType: string;
            }[];
            outputs: {
                name: string;
                type: string;
                internalType: string;
            }[];
        }[];
    };
    getSolidityVerifierParameters({ proof, validityPeriodInSeconds, domain, scope, devMode, }: {
        proof: ProofResult;
        validityPeriodInSeconds?: number;
        domain?: string;
        scope?: string;
        devMode?: boolean;
    }): SolidityVerifierParameters;
    private _getUrl;
    /**
     * @notice Returns the URL of the request.
     * @param requestId The request ID.
     * @returns The URL of the request.
     */
    getUrl(requestId: string): string;
    /**
     * @notice Cancels a request by closing the WebSocket connection and deleting the associated data.
     * @param requestId The request ID.
     */
    cancelRequest(requestId: string): void;
    /**
     * @notice Clears all requests.
     */
    clearAllRequests(): void;
}

export { QueryBuilder, QueryResultErrors, SolidityVerifierParameters, ZKPassport };
